      stCtx.fillStyle = i % 3 === 0 ? "rgba(70,66,60,0.28)" : i % 2 === 0 ? "rgba(210,204,192,0.25)" : "rgba(130,118,102,0.22)";
      stCtx.fillRect(px2, py2, 2, 2);
