  function buildClassicalModillionCornice(parent, x, z2, length, rotY, terraMat, trimMat) {
    const g = new Group();
    g.position.set(x, 0, z2);
    g.rotation.y = rotY;
    const bedMold = new Mesh(new BoxGeometry(length - 0.4, 0.24, 0.36), terraMat);
    bedMold.position.set(0, 16.57, 0.16);
    bedMold.castShadow = true;
    g.add(bedMold);
    const corona = new Mesh(new BoxGeometry(length, 0.34, 0.86), trimMat);
    corona.position.set(0, 17.09, 0.38);
    corona.castShadow = true;
    corona.receiveShadow = true;
    g.add(corona);
    const spacing = 0.72;
    const count = Math.max(4, Math.floor((length - 0.8) / spacing));
    const span = (count - 1) * spacing;
    for (let i = 0; i < count; i++) {
      const bx = -span * 0.5 + i * spacing;
      const modBracket = new Mesh(new BoxGeometry(0.22, 0.24, 0.62), trimMat);
      modBracket.position.set(bx, 16.81, 0.3);
      modBracket.castShadow = true;
      g.add(modBracket);
      const modScroll = new Mesh(new CylinderGeometry(0.08, 0.08, 0.24, 8), terraMat);
      modScroll.rotation.z = Math.PI * 0.5;
      modScroll.position.set(bx, 16.72, 0.52);
      g.add(modScroll);
    }
    parent.add(g);
  }

