    plinthMesh.userData = { isSelectableBuilding: true, building };
    arch.add(plinthMesh);
    const waterTableCap = new Mesh(
      new BoxGeometry(width + 0.24, 0.12, depth + 0.24),
      smoothGraniteMat
    );
    waterTableCap.position.set(midX, 0.36, midZ);
    arch.add(waterTableCap);
    const utilBox = new Mesh(
      new BoxGeometry(0.45, 0.72, 0.22),
      new MeshStandardMaterial({ color: "#c8cfd4", roughness: 0.5, metalness: 0.3 })
    );
    utilBox.position.set(minX + 1.85, -0.35, maxZ + 0.12);
    arch.add(utilBox);
    const fdcMat = new MeshStandardMaterial({ color: "#8a9298", roughness: 0.4, metalness: 0.7 });
    const fdcPipe = new Mesh(new CylinderGeometry(0.06, 0.06, 0.75, 10), fdcMat);
    fdcPipe.position.set(minX - 0.28, 0.38, minZ + 0.52);
    arch.add(fdcPipe);
    const fdcHead = new Mesh(new BoxGeometry(0.22, 0.16, 0.32), fdcMat);
    fdcHead.position.set(minX - 0.28, 0.76, minZ + 0.52);
