  function buildStairPipeHandrail(parent, x, zStart, yStart, zEnd, yEnd, mat) {
    const dz = zEnd - zStart;
    const dy = yEnd - yStart;
    const len = Math.hypot(dz, dy);
    const slopeAng = Math.atan2(-dy, dz);
    const midZ = (zStart + zEnd) * 0.5;
    const midY = (yStart + yEnd) * 0.5;
    [0.92, 0.56, 0.22].forEach((railH) => {
      const rail = new Mesh(new CylinderGeometry(0.022, 0.022, len, 8), mat);
      rail.rotation.x = Math.PI * 0.5 + slopeAng;
      rail.position.set(x, midY + railH, midZ);
      rail.castShadow = true;
      parent.add(rail);
    });
    const numPosts = Math.max(3, Math.round(Math.abs(dz) / 2.2) + 1);
    for (let i = 0; i < numPosts; i++) {
      const t = i / (numPosts - 1);
      const pz2 = MathUtils.lerp(zStart, zEnd, t);
      const py2 = MathUtils.lerp(yStart, yEnd, t);
      const post = new Mesh(new CylinderGeometry(0.024, 0.024, 0.94, 8), mat);
      post.position.set(x, py2 + 0.47, pz2);
      post.castShadow = true;
      parent.add(post);
    }
  }

  // js/foundry/buildings/building350/buildBuilding350.js
  function buildPhotoRealisticBuilding350(foundry, group, building, shape, wallMat, trimMat, terrainY = 0, getTerrainHeightFn = null) {
    const arch = new Group();
    arch.name = "Building350PhotoRealisticGroup";
    arch.rotation.y = Math.atan2(0.80439, 0.5941);
    const mats = createBuilding350Materials();
    buildBuilding350Structure(arch, building, mats);
    buildBuilding350FrontFascia(arch, mats);
    buildBuilding350Grounds(arch, mats, terrainY, getTerrainHeightFn);
    group.add(arch);
  }

