    const idx = [];
    for (let il = 0; il <= segsL; il++) {
      const u2 = il / segsL;
      const widthProfile = u2 < 0.15 ? 0.55 + u2 / 0.15 * 0.45 : Math.sqrt(Math.max(0.02, 1 - Math.pow((u2 - 0.15) / 0.85, 2.15)));
      const halfW = width * 0.5 * widthProfile;
      const x = u2 * length;
      const curlLift = Math.pow(u2, 2.4) * tipCurlY;
      for (let iw = 0; iw <= segsW; iw++) {
        const v2 = iw / segsW;
        const zLocal = (v2 - 0.58) * 2 * halfW;
        const arch = Math.sin(v2 * Math.PI) * camber * (1 - u2 * 0.45);
        const thickness = (1 - u2 * 0.75) * 55e-4 * Math.sin(v2 * Math.PI);
        pos.push(x, curlLift + arch + thickness, zLocal);
        uvs.push(u2, v2);
      }
    }
    const rowStride = segsW + 1;
    const upperVertCount = (segsL + 1) * rowStride;
    for (let il = 0; il <= segsL; il++) {
      const u2 = il / segsL;
      const widthProfile = u2 < 0.15 ? 0.55 + u2 / 0.15 * 0.45 : Math.sqrt(Math.max(0.02, 1 - Math.pow((u2 - 0.15) / 0.85, 2.15)));
      const halfW = width * 0.5 * widthProfile;
      const x = u2 * length;
      const curlLift = Math.pow(u2, 2.4) * tipCurlY;
      for (let iw = 0; iw <= segsW; iw++) {
        const v2 = iw / segsW;
        const zLocal = (v2 - 0.58) * 2 * halfW;
        const arch = Math.sin(v2 * Math.PI) * camber * (1 - u2 * 0.45);
        const thickness = (1 - u2 * 0.75) * 45e-4 * Math.sin(v2 * Math.PI);
        pos.push(x, curlLift + arch - thickness, zLocal);
        uvs.push(u2, v2);
      }
    }
    for (let il = 0; il < segsL; il++) {
      for (let iw = 0; iw < segsW; iw++) {
        const a2 = il * rowStride + iw;
        const b2 = a2 + 1;
        const c = (il + 1) * rowStride + iw;
        const d = c + 1;
        idx.push(a2, c, b2, b2, c, d);
        const la = upperVertCount + a2;
        const lb = upperVertCount + b2;
        const lc = upperVertCount + c;
        const ld = upperVertCount + d;
        idx.push(la, lb, lc, lb, ld, lc);
      }
    }
