          startPos: startPos.clone(),
          endPos: startPos.clone(),
          arcHeight: 4.5,
          swerveSign: Math.random() < 0.5 ? 1 : -1,
          swerveAmp: 1.5,
          flightDuration: 4,
          flightElapsed: 0,
