        const emissiveCol = baseCol.clone().lerp(new Color("#ffffff"), 0.28);
        const emissiveInt = isSelectedZone ? 0.48 : hasOtherSelected ? 0.2 : 0.36;
        const shape = new Shape();
        z2.poly.forEach(([px2, pz2], idx) => {
          if (idx === 0) shape.moveTo(px2, -pz2);
          else shape.lineTo(px2, -pz2);
        });
        shape.closePath();
